-- Ato de produção de 24/09/2026: as oito atestações de provedor passam a valer sem data de validade.
--
-- Decisão do fundador de 24/09/2026, registrada em docs/build/arcabouco-stage0/FOUNDER-ACTS.md e em
-- DECISION.md, neste diretório: a conferência de 21/09/2026 deixa de vencer por prazo. Cada atestação
-- ativa é substituída por uma identidade nova com o mesmo documento, a mesma evidência, a mesma revisão
-- e validThrough nulo; a anterior é revogada no mesmo ato. Só os comandos de operador existentes
-- escrevem nas tabelas de atestação. Os documentos novos estão em assurances.json, neste diretório.
--
-- Pré-requisito: a migração provider_assurance_without_expiry aplicada no mesmo banco. Executar como
-- postgres, o papel que os comandos exigem. Uma única transação: qualquer divergência aborta e nada
-- muda. Reexecutar depois de concluído não altera nada. Uma atestação anterior já revogada nunca é
-- trazida de volta. Staging recebeu as mesmas oito atestações em 21/09/2026 e serve de ensaio com este
-- mesmo arquivo; se algo mudou lá desde então, as pré-condições recusam antes de qualquer escrita.
begin;

-- Pares da substituição: identidade anterior com a impressão registrada em 21/09/2026, identidade nova
-- com a impressão que o comando calcula para o documento sem data.
create temporary table offroad_assurance_replacement(
 old_id uuid primary key, old_fingerprint text not null, new_id uuid not null unique, new_fingerprint text not null
) on commit drop;
insert into pg_temp.offroad_assurance_replacement(old_id,old_fingerprint,new_id,new_fingerprint) values
