 ('d01cc0a5-eb50-5be8-845f-ba95af813956','89d99417b411fda509a85e18d435fcbba79a298c9eb0d0a9a1935bc20ad41c2d','6b19be73-db55-59c7-b1a4-b9384027664f','fc927580932f8016fdc2858a0e6b1d1578624de75617b13097f745c9b6c20e02'), -- OpenAI, documento inline (gpt-5.6-sol, gpt-5.6-terra)
 ('32359b2e-1577-5b52-9e63-a59c08a6ab8a','96f2d310a953f96fb7fab5b77af35a5d83f733bdb1a55b84e535aadc13e13d27','81068b66-d0d5-5d11-bdb5-4dade80decfa','4d71c4e18a57274a53fb96a4945b97b237b0646dbd92f59a2305ec269a449b3d'), -- OpenAI, cache de prompt (gpt-5.6-sol, gpt-5.6-terra)
 ('1cfb9f84-4949-5c1f-bbb6-2d4d610173f3','6601cebc5b83fc950c2ced661e91cb7f0fb37be5ced0ae60abfbe618932c2757','58796c63-7c1d-5368-9fbb-b91141bde4a6','1a05a1e46ca1d9eb8382c74833f448b51d5937f0e5fa7b8330b729fa509720a4'), -- OpenAI, pesquisa externa (gpt-5.6-terra)
