 ('94c21626-ff07-5a65-aee0-77e2255dfb16','1ec039d29f97907c7b1e59d5078c70211273c95e44d6d4c2a2ac494c6b7de9cf','0e988d87-6581-5bbc-b189-ebd871509767','d59c75cab5f2ac9f89e9478c2f86aa21ffa07f4425f180e5916cecafa84d55fc'), -- Anthropic, documento inline (claude-opus-5, claude-sonnet-5)
