 ('e022b26c-d76a-5343-858b-85609050fd4c','f0ca682f9c8e397705ceef01524733a8185f863e1f3658ddeda5845cb3e46261','70398e5f-bc7f-5104-a031-f76c1517b93c','6d700c4e8460d0be809f23cbbd7f5cdfdf19e9a894ba330bd014489c68a3c57f'); -- Anthropic, cache de schema (claude-opus-5, claude-sonnet-5)

-- Pré-condições, sob o mesmo bloqueio que os comandos e as decisões de elegibilidade usam: enquanto o ato
-- corre, o worker espera a decisão em vez de encontrar a troca pela metade.
do $$declare r record; a private.provider_processing_assurances; n private.provider_processing_assurances;begin
 perform pg_advisory_xact_lock(hashtextextended('provider-processing-assurances',0));
 if (select attnotnull from pg_attribute where attrelid='private.provider_processing_assurances'::regclass and attname='valid_through')
 then raise exception 'provider_assurance_act_requires_migration';end if;
 for r in select * from pg_temp.offroad_assurance_replacement loop
  select * into a from private.provider_processing_assurances where id=r.old_id;
  if not found or a.fingerprint<>r.old_fingerprint then raise exception 'provider_assurance_act_previous_differs: %',r.old_id;end if;
  select * into n from private.provider_processing_assurances where id=r.new_id;
  if not found then
   if a.revoked_at is not null then raise exception 'provider_assurance_act_previous_revoked: %',r.old_id;end if;
  elsif n.fingerprint<>r.new_fingerprint or n.revoked_at is not null or a.revoked_at is null then
   raise exception 'provider_assurance_act_unexpected_state: %',r.new_id;
  end if;
 end loop;
end $$;

