-- Pós-condições: cada anterior revogada, cada nova ativa e sem data, com o documento anterior sob outra
-- identidade, um registro de operador por comando, e a autoridade de elegibilidade respondendo com a
-- identidade nova em todo o escopo que a anterior cobria (modelos, finalidades e classes).
do $$declare r record; a private.provider_processing_assurances; n private.provider_processing_assurances; m text; p text; c text;begin
 for r in select * from pg_temp.offroad_assurance_replacement loop
  select * into strict a from private.provider_processing_assurances where id=r.old_id;
  select * into strict n from private.provider_processing_assurances where id=r.new_id;
  if a.revoked_at is null or n.revoked_at is not null or n.valid_through is not null or n.fingerprint<>r.new_fingerprint
  or n.document is distinct from a.document||jsonb_build_object('id',r.new_id,'validThrough',null)
  or (n.provider,n.account_ref,n.project_ref,n.credential_binding,n.endpoint,n.resource,n.region,n.reviewed_at)
   is distinct from (a.provider,a.account_ref,a.project_ref,a.credential_binding,a.endpoint,a.resource,a.region,a.reviewed_at)
  or (select count(*) from private.provider_processing_assurance_events e where e.assurance_id=r.new_id and e.action='recorded' and e.fingerprint=r.new_fingerprint)<>1
  or (select count(*) from private.provider_processing_assurance_events e where e.assurance_id=r.old_id and e.action='revoked')<>1
  then raise exception 'provider_assurance_act_not_applied: %',r.new_id;end if;
  for m in select jsonb_array_elements_text(n.document->'models') loop
   for p in select jsonb_array_elements_text(n.document->'purposes') loop
    for c in select jsonb_array_elements_text(n.document->'classifications') loop
     if private.provider_resource_allowed_v1(jsonb_build_object('provider',n.provider,'model',m,'accountRef',n.account_ref,'projectRef',n.project_ref,
      'credentialBinding',n.credential_binding,'endpoint',n.endpoint,'region',n.region),n.resource,p,c,2592000) is distinct from n.id
     then raise exception 'provider_assurance_act_not_eligible: % % % %',n.id,m,p,c;end if;
    end loop;
   end loop;
  end loop;
 end loop;
end $$;

select x.new_id as id,a.provider,a.resource,a.document->'models' as models,a.valid_through,a.fingerprint,x.old_id as replaces
from pg_temp.offroad_assurance_replacement x join private.provider_processing_assurances a on a.id=x.new_id
order by a.provider,a.resource;
commit;
